def semver_sort(versions):
    def parse_version(version):
        # Split build metadata (everything after '+')
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version

        # Split pre-release (everything after '-')
        if '-' in version_part:
            core_part, prerelease = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            # Convert identifiers to comparable form
            parsed_prerelease = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    parsed_prerelease.append((0, int(identifier)))
                else:
                    parsed_prerelease.append((1, identifier))
        else:
            parsed_prerelease = None

        return (major, minor, patch, prerelease_identifiers if prerelease else None, parsed_prerelease)

    def sort_key(item):
        version, original_index = item
        major, minor, patch, _, parsed_prerelease = version

        # For sorting:
        # 1. Compare major, minor, patch numerically
        # 2. If one has prerelease and other doesn't, one without prerelease sorts later
        # 3. If both have prerelease, compare identifiers
        # 4. Use original index for stable sort (maintain input order for equal precedence)

        if parsed_prerelease is None:
            # No prerelease: sort after versions with same core but with prerelease
            return (major, minor, patch, 1, (), original_index)
        else:
            # Has prerelease: sort before versions with same core but without prerelease
            return (major, minor, patch, 0, tuple(parsed_prerelease), original_index)

    parsed_versions = [parse_version(v) for v in versions]
    indexed_versions = list(zip(parsed_versions, range(len(versions))))
    sorted_indexed = sorted(indexed_versions, key=sort_key)

    return [versions[i] for _, i in sorted_indexed]

